45	
46	#[typst_macros::time(name = "convert document")]
47	pub fn convert(
48	    typst_document: &PagedDocument,
49	    options: &PdfOptions,
50	    anchors: &[(Location, EcoString)],
51	    link_resolver: Option<Tracked<LateLinkResolver>>,
52	    warnings: &mut EcoVec<SourceDiagnostic>,
53	) -> SourceResult<Vec<u8>> {
54	    let options =
55	        options.resolve(typst_document.options().get::<PdfFormat>(), warnings)?;
56	
57	    let tags = tags::init(typst_document, &options)?;
58	
59	    let settings = SerializeSettings {
60	        compress_content_streams: !options.format.pretty.v,
61	        no_device_cs: true,
62	        ascii_compatible: options.format.pretty.v,
63	        xmp_metadata: true,
64	        cmyk_profile: None,
65	        configuration: options.format.standard.v.config,
66	        enable_tagging: options.tagged(),
67	        render_svg_glyph_fn: render_svg_glyph,
68	        pretty: options.format.pretty.v,
69	    };
70	
71	    let mut document = Document::new_with(settings);
72	    let page_index_converter = PageIndexConverter::new(typst_document, &options);
73	    let named_destinations = collect_named_destinations(
74	        &mut document,
75	        typst_document,
76	        anchors,
77	        &page_index_converter,
78	    );
79	
80	    let mut gc = GlobalContext::new(
81	        typst_document,
82	        &options,
83	        link_resolver,
84	        named_destinations,
85	        page_index_converter,
86	        tags,
87	    );
88	
89	    convert_pages(&mut gc, &mut document)?;
90	    attach_files(&gc, &mut document)?;
91	    let (doc_lang, tree) = tags::resolve(&mut gc)?;
92	
93	    document.set_outline(build_outline(&gc));
94	    document.set_metadata(build_metadata(&gc, doc_lang));
95	    document.set_tag_tree(tree);
96	
97	    finish(document, gc)
98	}
99	
100	fn convert_pages(gc: &mut GlobalContext, document: &mut Document) -> SourceResult<()> {
101	    for (i, typst_page) in gc.document.pages().iter().enumerate() {
102	        if gc.page_index_converter.pdf_page_index(i).is_none() {
103	            // Don't export this page.
104	            continue;
105	        }
106	
107	        // PDF 1.4 upwards to 1.7 specifies a minimum page size of 3x3 units.
108	        // PDF 2.0 doesn't define an explicit limit, but krilla and probably
109	        // some viewers won't handle pages that have zero sized pages.
110	        let mut settings = PageSettings::from_wh(
111	            (typst_page.frame.width() + typst_page.bleed.left + typst_page.bleed.right)
112	                .to_f32()
113	                .max(3.0),
114	            (typst_page.frame.height() + typst_page.bleed.top + typst_page.bleed.bottom)
115	                .to_f32()
116	                .max(3.0),
117	        )
118	        .expect_internal("invalid page size")
119	        .at(Span::detached())?;
120	
121	        if !typst_page.bleed.is_zero() {
122	            settings = settings.with_trim_box(Rect::from_ltrb(
123	                typst_page.bleed.left.to_f32(),
124	                typst_page.bleed.top.to_f32(),
125	                (typst_page.bleed.left + typst_page.frame.width()).to_f32(),
126	                (typst_page.bleed.top + typst_page.frame.height()).to_f32(),
127	            ));
128	        }
129	
130	        if let Some(label) = typst_page
131	            .numbering
132	            .as_ref()
133	            .and_then(|num| PageLabel::generate(num, typst_page.number))
134	            .or_else(|| {
135	                // When some pages were ignored from export, we show a page label with
136	                // the correct real (not logical) page number.
137	                // This is for consistency with normal output when pages have no numbering
138	                // and all are exported: the final PDF page numbers always correspond to
139	                // the real (not logical) page numbers. Here, the final PDF page number
140	                // will differ, but we can at least use labels to indicate what was
141	                // the corresponding real page number in the Typst document.
142	                gc.page_index_converter
143	                    .has_skipped_pages()
144	                    .then(|| PageLabel::arabic((i + 1) as u64))
145	            })
146	        {
147	            settings = settings.with_page_label(label);
148	        }
149	
150	        let mut page = document.start_page_with(settings);
151	        let mut surface = page.surface();
152	        let page_idx = gc.page_index_converter.pdf_page_index(i);
153	        let mut fc = FrameContext::new(
154	            page_idx,
155	            typst_page.frame.size() + typst_page.bleed.sum_by_axis(),
156	        );
157	
158	        tags::page(gc, &mut surface, |gc, surface| {
159	            handle_frame(
160	                &mut fc,
161	                &typst_page.frame,
162	                typst_page.bleed,
163	                typst_page.fill_or_transparent(),
164	                surface,
165	                gc,
166	            )
167	        })?;
168	
169	        surface.finish();
170	
171	        let link_annotations = fc.link_annotations.into_values().flatten();
172	        tags::add_link_annotations(gc, &mut page, link_annotations);
173	    }
174	
175	    Ok(())
176	}
