330	#[typst_macros::time(name = "handle page")]
331	pub(crate) fn handle_frame(
332	    fc: &mut FrameContext,
333	    frame: &Frame,
334	    padding: Sides<Abs>,
335	    fill: Option<Paint>,
336	    surface: &mut Surface,
337	    gc: &mut GlobalContext,
338	) -> SourceResult<()> {
339	    fc.push();
340	
341	    if frame.kind().is_hard() {
342	        fc.state_mut().register_container(frame.size());
343	    }
344	
345	    if let Some(fill) = fill {
346	        let shape = Geometry::Rect(frame.size() + padding.sum_by_axis()).filled(fill);
347	        handle_shape(
348	            fc,
349	            &shape,
350	            surface,
351	            gc,
352	            Span::detached(),
353	            Smart::Custom(ArtifactType::Background),
354	        )?;
355	    }
356	
357	    fc.push();
358	    fc.state_mut()
359	        .pre_concat(Transform::translate(padding.left, padding.top));
360	
361	    for (point, item) in frame.items() {
362	        fc.push();
363	        fc.state_mut().pre_concat(Transform::translate(point.x, point.y));
364	
365	        match item {
366	            FrameItem::Group(g) => handle_group(fc, g, surface, gc)?,
367	            FrameItem::Text(t) => handle_text(fc, t, surface, gc)?,
368	            FrameItem::Shape(s, span) => {
369	                handle_shape(fc, s, surface, gc, *span, Smart::Auto)?;
370	            }
371	            FrameItem::Image(image, size, span) => {
372	                handle_image(gc, fc, image, *size, surface, *span)?;
373	            }
374	            FrameItem::Link(dest, size) => handle_link(fc, gc, dest, *size)?,
375	            FrameItem::Tag(Tag::Start(_, flags)) => {
376	                if flags.tagged {
377	                    tags::handle_start(gc, fc, surface);
378	                }
379	            }
380	            FrameItem::Tag(Tag::End(_, _, flags)) => {
381	                if flags.tagged {
382	                    tags::handle_end(gc, fc, surface);
383	                }
384	            }
385	        }
386	
387	        fc.pop();
388	    }
389	
390	    fc.pop();
391	    fc.pop();
392	
393	    Ok(())
394	}
395	
396	pub(crate) fn handle_group(
397	    fc: &mut FrameContext,
398	    group: &GroupItem,
399	    surface: &mut Surface,
400	    gc: &mut GlobalContext,
401	) -> SourceResult<()> {
402	    fc.push();
403	    fc.state_mut().pre_concat(group.transform);
404	
405	    tags::group(gc, fc, surface, group.parent, |gc, fc, surface| {
406	        let clip_path = group
407	            .clip
408	            .as_ref()
409	            .and_then(|p| {
410	                let mut builder = PathBuilder::new();
411	                convert_path(p, &mut builder);
412	                builder.finish()
413	            })
414	            .and_then(|p| p.transform(fc.state().transform.to_krilla()));
415	
416	        if let Some(clip_path) = &clip_path {
417	            surface.push_clip_path(clip_path, &krilla::paint::FillRule::NonZero);
418	        }
419	
420	        let res =
421	            handle_frame(fc, &group.frame, Sides::splat(Abs::zero()), None, surface, gc);
422	
423	        if clip_path.is_some() {
424	            surface.pop();
425	        }
426	
427	        res
428	    })?;
429	
430	    fc.pop();
431	
432	    Ok(())
433	}
