435	/// Finish a krilla document and handle export errors.
436	#[typst_macros::time(name = "finish export")]
437	fn finish(document: Document, gc: GlobalContext) -> SourceResult<Vec<u8>> {
438	    match document.finish() {
439	        Ok(bytes) => Ok(bytes),
440	        Err(err) => match err {
441	            KrillaError::Font(f, err) => {
442	                bail!(
443	                    Span::detached(),
444	                    "failed to process {} ({err})",
445	                    display_font(gc.fonts_backward.get(&f));
446	                    hint: "make sure the font is valid";
447	                    hint: "the used font might be unsupported by Typst";
448	                )
449	            }
450	            KrillaError::Validation(ve) => Err(ve
451	                .iter()
452	                .map(|(e, validators)| convert_validation_error(&gc, e, *validators))
453	                .collect()),
454	            KrillaError::Image(_, loc, err) => {
455	                let span = to_span(loc);
456	                bail!(span, "failed to process image ({err})");
457	            }
458	            KrillaError::SixteenBitImage(image, _) => {
459	                let span = &gc.image_to_spans[&image];
460	                bail!(
461	                    *span, "16 bit images are not supported in this export mode";
462	                    hint: "convert the image to 8 bit instead";
463	                )
464	            }
465	            KrillaError::Pdf(_, e, loc) => {
466	                let span = to_span(loc);
467	                match e {
468	                    // We already validated in `typst-library` that the page index is valid.
469	                    PdfError::InvalidPage(_) => bail!(
470	                        span,
471	                        "invalid page number for PDF file";
472	                        hint: "please report this as a bug";
473	                    ),
474	                    PdfError::VersionMismatch(embedded) => {
475	                        let embedded = embedded.as_str();
476	                        let target = gc.options.version().as_str();
477	                        bail!(span,
478	                            "the version of the PDF is too high";
479	                            hint: "the current export target is {target}, while the PDF \
480	                                   has version {embedded}";
481	                            hint: "raise the export target to {embedded} or higher";
482	                            hint: "or preprocess the PDF to convert it to a lower version";
483	                        );
484	                    }
485	                }
486	            }
487	            KrillaError::DuplicateTagId(_, loc) => {
488	                let span = to_span(loc);
489	                bail!(span,
490	                    "duplicate tag id";
491	                    hint: "please report this as a bug";
492	                );
493	            }
494	            KrillaError::UnknownTagId(_, loc) => {
495	                let span = to_span(loc);
496	                bail!(span,
497	                    "unknown tag id";
498	                    hint: "please report this as a bug";
499	                );
500	            }
501	            KrillaError::DuplicateNamedDestination(_) => {
502	                bail!(Span::detached(),
503	                    "duplicate named destination";
504	                    hint: "please report this as a bug";
505	                );
506	            }
507	            KrillaError::Limit(LimitError::TooLongArray) => bail!(
508	                Span::detached(),
509	                "a PDF array is longer than 8191 elements";
510	                hint: "set the PDF version to PDF 1.5 or later";
511	                hint: "this can happen if you have a very long text in a single line";
512	            ),
513	            KrillaError::Limit(LimitError::TooLongDictionary) => bail!(
514	                Span::detached(),
515	                "a PDF dictionary has more than 4095 entries";
516	                hint: "set the PDF version to PDF 1.5 or later";
517	                hint: "alternatively, try reducing the complexity of your document";
518	            ),
519	            KrillaError::Limit(LimitError::TooLargeFloat) => bail!(
520	                Span::detached(),
521	                "a PDF floating point number is larger than the allowed limit";
522	                hint: "set the PDF version to PDF 1.5 or later";
523	            ),
524	        },
525	    }
526	}
