528	/// Converts a krilla error into a Typst error.
529	fn convert_validation_error(
530	    gc: &GlobalContext,
531	    error: &ValidationError,
532	    failing_validators: Validators,
533	) -> SourceDiagnostic {
534	    let pdf_version = gc.options.version().as_str();
535	    let prefix = eco_format!("{} error:", failing_validators.to_comma_list());
536	    match error {
537	        ValidationError::TooLongString => error!(
538	            Span::detached(),
539	            "{prefix} a PDF string is longer than 32767 characters";
540	            hint: "ensure title and author names are short enough";
541	        ),
542	        // Should in theory never occur, as krilla always trims font names.
543	        ValidationError::TooLongName => error!(
544	            Span::detached(),
545	            "{prefix} a PDF name is longer than 127 characters";
546	            hint: "perhaps a font name is too long";
547	        ),
548	
549	        ValidationError::TooLongArray => error!(
550	            Span::detached(),
551	            "{prefix} a PDF array is longer than 8191 elements";
552	            hint: "this can happen if you have a very long text in a single line";
553	        ),
554	        ValidationError::TooLongDictionary => error!(
555	            Span::detached(),
556	            "{prefix} a PDF dictionary has more than 4095 entries";
557	            hint: "try reducing the complexity of your document";
558	        ),
559	        ValidationError::TooLargeFloat => error!(
560	            Span::detached(),
561	            "{prefix} a PDF floating point number is larger than the allowed limit";
562	            hint: "try exporting with a higher PDF version";
563	        ),
564	        ValidationError::TooManyIndirectObjects => error!(
565	            Span::detached(),
566	            "{prefix} the PDF has too many indirect objects";
567	            hint: "reduce the size of your document";
568	        ),
569	        // Can only occur if we have 27+ nested clip paths
570	        ValidationError::TooHighQNestingLevel => error!(
571	            Span::detached(),
572	            "{prefix} the PDF has too high q nesting";
573	            hint: "reduce the number of nested containers";
574	        ),
575	        ValidationError::ContainsPostScript(loc) => error!(
576	            to_span(*loc),
577	            "{prefix} the PDF contains PostScript code";
578	            hint: "conic gradients are not supported in this PDF standard";
579	        ),
580	        ValidationError::MissingCMYKProfile => error!(
581	            Span::detached(),
582	            "{prefix} the PDF is missing a CMYK profile";
583	            hint: "CMYK colors are not yet supported in this export mode";
584	        ),
585	        ValidationError::InconsistentSeparationFallback(colorant) => {
586	            let repr = Option::<SpotColorantName>::from_krilla(colorant).repr();
587	            error!(
588	                Span::detached(),
589	                "spot colorant `{repr}` appeared with multiple distinct fallback colors";
590	                hint: "define a particular spot colorant once and store it in a variable to reuse it later";
591	            )
592	        }
593	        ValidationError::ContainsNotDefGlyph(f, loc, text) => error!(
594	            to_span(*loc),
595	            "{prefix} the text `{}` could not be displayed with {}",
596	            text.repr(),
597	            display_font(gc.fonts_backward.get(f));
598	            hint: "try using a different font";
599	        ),
600	        ValidationError::NoCodepointMapping(_, _, loc) => {
601	            let msg = if loc.is_some() {
602	                "the text was not mapped to a code point"
603	            } else {
604	                "the PDF contains text with missing codepoints"
605	            };
606	            error!(
607	                to_span(*loc),
608	                "{prefix} {msg}";
609	                hint: "for complex scripts like Arabic, it might not be \
610	                       possible to produce a compliant document";
611	            )
612	        }
613	        ValidationError::InvalidCodepointMapping(_, _, c, loc) => {
614	            let msg = if loc.is_some() {
615	                "the text contains"
616	            } else {
617	                "the PDF contains text with"
618	            };
619	            error!(
620	                to_span(*loc),
621	                "{prefix} {msg} the disallowed codepoint `{}`",
622	                c.repr(),
623	            )
624	        }
625	        ValidationError::UnicodePrivateArea(_, _, c, loc) => {
626	            let msg = if loc.is_some() { "the PDF" } else { "the text" };
627	            error!(
628	                to_span(*loc),
629	                "{prefix} {msg} contains the codepoint `{}`", c.repr();
630	                hint: "codepoints from the Unicode private area are \
631	                       forbidden in this export mode";
632	            )
633	        }
634	        ValidationError::RestrictedLicense(f) => error!(
635	            Span::detached(),
636	            "{prefix} license of {} is too restrictive",
637	            display_font(gc.fonts_backward.get(f));
638	            hint: "the font has specified \"Restricted License embedding\" in its \
639	                   metadata";
640	            hint: "restrictive font licenses are prohibited by {} because they limit \
641	                   the suitability for archival",
642	            failing_validators.to_and_list();
643	        ),
644	        ValidationError::Transparency(loc) => {
645	            let span = to_span(*loc);
646	            let hint1 = "try exporting with a different standard that \
647	                         supports transparency";
648	            if loc.is_some() {
649	                if gc.image_spans.contains(&span) {
650	                    error!(
651	                        span, "{prefix} the image contains transparency";
652	                        hint: "{hint1}";
653	                        hint: "or convert the image to a non-transparent one";
654	                        hint: "you might have to convert SVGs into \
655	                               non-transparent bitmap images";
656	                    )
657	                } else {
658	                    error!(
659	                        span, "{prefix} the used fill or stroke has transparency";
660	                        hint: "{hint1}";
661	                        hint: "or don't use colors with transparency in \
662	                               this export mode";
663	                    )
664	                }
665	            } else {
666	                error!(
667	                    span, "{prefix} the PDF contains transparency";
668	                    hint: "{hint1}";
669	                )
670	            }
671	        }
672	        ValidationError::ImageInterpolation(loc) => {
673	            let span = to_span(*loc);
674	            if loc.is_some() {
675	                error!(
676	                    span, "{prefix} the image has smooth scaling";
677	                    hint: "set the `scaling` attribute to `pixelated`";
678	                )
679	            } else {
680	                error!(
681	                    span, "{prefix} an image in the PDF has smooth scaling";
682	                    hint: "set the `scaling` attribute of all images to `pixelated`";
683	                )
684	            }
685	        }
686	        ValidationError::EmbeddedFile(e, s) => {
687	            // We always set the span for attached files, so it cannot be detached.
688	            let span = to_span(*s);
689	            match e {
690	                EmbedError::Existence => {
691	                    error!(
692	                        span, "{prefix} document contains an attached file";
693	                        hint: "file attachments are not supported in this export mode";
694	                    )
695	                }
696	                EmbedError::MissingDate => {
697	                    error!(
698	                        span, "{prefix} document date is missing";
699	                        hint: "the document must have a date when attaching files";
700	                        hint: "`set document(date: none)` must not be used in this case";
701	                    )
702	                }
703	                EmbedError::MissingDescription => {
704	                    error!(span, "{prefix} the file description is missing")
705	                }
706	                EmbedError::MissingMimeType => {
707	                    error!(span, "{prefix} the file mime type is missing")
708	                }
709	            }
710	        }
711	        // The below errors cannot occur yet, only once Typst supports full PDF/A
712	        // and PDF/UA. But let's still add a message just to be on the safe side.
713	        ValidationError::MissingAnnotationAltText(loc) => {
714	            let span = to_span(*loc);
715	            error!(
716	                span, "{prefix} missing annotation alt text";
717	                hint: "please report this as a bug";
718	            )
719	        }
720	        ValidationError::MissingAltText(loc) => {
721	            let span = to_span(*loc);
722	            error!(
723	                span, "{prefix} missing alt text";
724	                hint: "make sure your images and equations have alt text";
725	            )
726	        }
727	        ValidationError::MissingFieldAltName(loc) => {
728	            let span = to_span(*loc);
729	            error!(
730	                span, "{prefix} missing alt name";
731	                hint: "make sure your form fields have an alt name";
732	            )
733	        }
734	        ValidationError::NoDocumentLanguage => error!(
735	            Span::detached(),
736	            "{prefix} missing document language";
737	            hint: "set the language of the document";
738	        ),
739	        // Needs to be set by typst-pdf.
740	        ValidationError::MissingHeadingTitle => error!(
741	            Span::detached(),
742	            "{prefix} missing heading title";
743	            hint: "please report this as a bug";
744	        ),
745	        ValidationError::MissingDocumentOutline => error!(
746	            Span::detached(),
747	            "{prefix} missing document outline";
748	            hint: "please report this as a bug";
749	        ),
750	        ValidationError::MissingTagging => error!(
751	            Span::detached(),
752	            "{prefix} missing document tags";
753	            hint: "please report this as a bug";
754	        ),
755	        ValidationError::NoDocumentTitle => error!(
756	            Span::detached(),
757	            "{prefix} missing document title";
758	            hint: "set the title with `set document(title: [...])`";
759	        ),
760	        ValidationError::MissingDocumentDate => error!(
761	            Span::detached(),
762	            "{prefix} missing document date";
763	            hint: "set the date of the document";
764	        ),
765	        // This should never happen as Typst does not support setting rollover or down appearance
766	        ValidationError::AnnotationHasConditionalAppearance(loc) => {
767	            let span = to_span(*loc);
768	            error!(
769	                span, "{prefix} annotation has rollover or down appearance";
770	                hint: "please report this as a bug";
771	            )
772	        }
773	        ValidationError::ContainsMutatingAction(loc) => {
774	            let span = to_span(*loc);
775	            error!(
776	                span, "{prefix} document contains an action that may change its visual appearance";
777	                hint: "remove the action from the element";
778	            )
779	        }
780	        ValidationError::ContainsAdditionalActions(loc) => {
781	            let span = to_span(*loc);
782	            error!(
783	                span, "{prefix} annotation performs an action when clicked";
784	                hint: "actions are not supported in this PDF standard";
785	                hint: "remove the action from the element";
786	            )
787	        }
788	        ValidationError::EmbeddedPDF(loc) => {
789	            error!(
790	                to_span(*loc),
791	                "embedding PDFs is currently not supported in this export mode";
792	                hint: "try converting the PDF to an SVG before embedding it";
793	            )
794	        }
795	        ValidationError::RequiresNewerPdfVersion(feature, loc) => {
796	            let span = to_span(*loc);
797	            let message = match feature {
798	                VersionedFeature::StructureOrderTabbing => {
799	                    eco_format!(
800	                        "{prefix} links and other annotations cannot be navigated accessibly in {pdf_version} files"
801	                    )
802	                }
803	                VersionedFeature::HeaderFooterArtifactSubtypes => {
804	                    eco_format!(
805	                        "{prefix} headers and footers cannot be made accessible in {pdf_version} files"
806	                    )
807	                }
808	                VersionedFeature::TableHeaderScope => {
809	                    eco_format!(
810	                        "{prefix} table header cell cannot be accessibly tagged in {pdf_version} files"
811	                    )
812	                }
813	            };
814	
815	            let diagnostic = SourceDiagnostic::error(span, message);
816	
817	            let min_version = feature.minimum_pdf_version();
818	
819	            let mut most_restrictive: Option<(Validator, PdfVersion)> = None;
820	            for validator in gc.options.validators() {
821	                let max = validator.max();
822	                if most_restrictive.is_none_or(|(_, prev_max)| prev_max > max) {
823	                    most_restrictive = Some((validator, max));
824	                }
825	            }
826	
827	            let Some((restrictive_validator, max_version)) = most_restrictive else {
828	                // Does not happen in practice: A validator is required to raise
829	                // this error and they always have a maximum version.
830	                return diagnostic;
831	            };
832	
833	            if min_version < max_version {
834	                diagnostic.with_hint(eco_format!(
835	                    "select a version between {} and {}",
836	                    min_version.as_str(),
837	                    max_version.as_str(),
838	                ))
839	            } else if min_version == max_version {
840	                diagnostic
841	                    .with_hint(eco_format!("set the version to {}", min_version.as_str()))
842	            } else {
843	                diagnostic
844	                    .with_hint(eco_format!(
845	                        "PDF version must be at least {} to satisfy {}",
846	                        min_version.as_str(),
847	                        failing_validators.to_and_list(),
848	                    ))
849	                    .with_hint(eco_format!(
850	                        "remove or replace the {} standard, \
851	                         as it prevents PDF versions beyond {}",
852	                        restrictive_validator.as_str(),
853	                        max_version.as_str(),
854	                    ))
855	            }
856	        }
857	    }
858	}
859	
860	/// Convert a krilla location to a span.
861	pub(crate) fn to_span(loc: Option<krilla::surface::Location>) -> Span {
862	    loc.map(Span::from_raw).unwrap_or(Span::detached())
863	}
864	
865	fn collect_named_destinations(
866	    document: &mut Document,
867	    typst_document: &PagedDocument,
868	    anchors: &[(Location, EcoString)],
869	    pic: &PageIndexConverter,
870	) -> FxHashMap<Location, NamedDestination> {
871	    let mut locs_to_names = FxHashMap::default();
872	
873	    // Find all headings that have a label and are the first among other
874	    // headings with the same label.
875	    let mut seen = FxHashSet::default();
876	    let headings = typst_document.introspector().query(&HeadingElem::ELEM.select());
877	    let matches = anchors
878	        .iter()
879	        .map(|(loc, anchor)| (*loc, anchor.to_string()))
880	        .chain(
881	            headings
882	                .iter()
883	                .filter_map(|elem| elem.location().zip(elem.label()))
884	                .map(|(loc, label)| (loc, label.resolve().to_string())),
885	        )
886	        .filter(|(_, name)| seen.insert(name.clone()));
887	
888	    for (loc, name) in matches {
889	        // Only add named destination if page belonging to the position is exported.
890	        let pos = typst_document
891	            .introspector()
892	            .position(loc)
893	            .unwrap_or(PagedPosition::ORIGIN);
894	        if let Some(dest) = crate::link::pos_to_xyz(pic, pos) {
895	            let named = NamedDestination::new(name, dest);
896	            // The option is `None` if the destination is a duplicate which
897	            // should not happen because we filtered them on a set insert above,
898	            // hence the unwrap.
899	            document.register_named_destination(named.clone()).unwrap();
900	            locs_to_names.insert(loc, named);
901	        }
902	    }
903	
904	    locs_to_names
905	}
906	
907	pub(crate) struct PageIndexConverter {
908	    page_indices: FxHashMap<usize, usize>,
909	    skipped_pages: usize,
910	}
911	
912	impl PageIndexConverter {
913	    pub fn new(document: &PagedDocument, options: &PdfOptions<Complete>) -> Self {
914	        let mut page_indices = FxHashMap::default();
915	        let mut skipped_pages = 0;
916	
917	        for i in 0..document.pages().len() {
918	            if let Some(ranges) = &options.format.pages.v
919	                && !ranges.includes_page_index(i)
920	            {
921	                skipped_pages += 1;
922	            } else {
923	                page_indices.insert(i, i - skipped_pages);
924	            }
925	        }
926	
927	        Self { page_indices, skipped_pages }
928	    }
929	
930	    pub(crate) fn has_skipped_pages(&self) -> bool {
931	        self.skipped_pages > 0
932	    }
933	
934	    /// Get the PDF page index of a page index, if it's not excluded.
935	    pub(crate) fn pdf_page_index(&self, page_index: usize) -> Option<usize> {
936	        self.page_indices.get(&page_index).copied()
937	    }
938	}
